using System.Text;
using System.Text.RegularExpressions;

namespace SWLOR.RecipeParameters;

/// <summary>
/// The generated parameter table for recipes built in a loop over a generated catalog (the space revamp's module, hull, component and
/// ammo catalogs), whose rows the generator cannot edit because their source is regenerated by another tool. Such a loop reads its
/// recipe's parameters with <c>.MinigameParameters(RecipeParameterTable.For(row.RecipeType))</c>, and <c>write &lt;Key&gt;</c> keeps one
/// explicit entry per recipe here, so the values stay reviewable, stable and checked by the coverage tests like every other recipe's.
/// </summary>
public static class RecipeParameterTableFile
{
    /// <summary>The table's file, relative to the recipe definition folder.</summary>
    public const string FileName = "RecipeParameterTable.cs";

    /// <summary>The class a table-driven recipe chain names in its MinigameParameters call.</summary>
    public const string ClassName = "RecipeParameterTable";

    private const string Indent = "            ";

    private static readonly Regex Entry = new(
        @"^\s*\[RecipeType\.(?<recipe>\w+)\]\s*=\s*new\s+(?<type>\w+)\((?<arguments>.*)\),\s*$",
        RegexOptions.Compiled);

    /// <summary>
    /// Replaces the profile's entries (its parameter type, on a recipe <paramref name="ownedByProfile"/> accepts) with one per listed
    /// recipe, keeping every other entry. Returns the new file text, which equals <paramref name="text"/> when nothing changed.
    /// </summary>
    public static string Update(
        string text,
        string parameterType,
        IEnumerable<(string Recipe, string Arguments)> entries,
        Func<string, bool> ownedByProfile,
        out int changedEntries)
    {
        var eol = text.Contains("\r\n") ? "\r\n" : "\n";
        var lines = text.Split(eol);
        var open = Array.FindIndex(lines, line => line.TrimEnd().EndsWith("_parameters = new()", StringComparison.Ordinal));
        if (open < 0 || open + 1 >= lines.Length || lines[open + 1].Trim() != "{")
            throw new RecipeSourceWriterException($"{FileName}: the _parameters dictionary initializer was not found");

        var close = Array.FindIndex(lines, open + 2, line => line.Trim() == "};");
        if (close < 0)
            throw new RecipeSourceWriterException($"{FileName}: the _parameters dictionary initializer is not closed");

        var current = new Dictionary<string, (string Type, string Arguments)>(StringComparer.Ordinal);
        for (var index = open + 2; index < close; index++)
        {
            if (string.IsNullOrWhiteSpace(lines[index]))
                continue;

            var match = Entry.Match(lines[index]);
            if (!match.Success)
                throw new RecipeSourceWriterException($"{FileName}({index + 1}): unsupported table entry: {lines[index].Trim()}");

            current[match.Groups["recipe"].Value] = (match.Groups["type"].Value, match.Groups["arguments"].Value);
        }

        var wanted = entries.ToDictionary(entry => entry.Recipe, entry => (Type: parameterType, entry.Arguments), StringComparer.Ordinal);
        var next = current.Where(pair => !(pair.Value.Type == parameterType && ownedByProfile(pair.Key)) && !wanted.ContainsKey(pair.Key))
            .Concat(wanted)
            .ToDictionary(pair => pair.Key, pair => pair.Value, StringComparer.Ordinal);

        changedEntries = next.Count(pair => !current.TryGetValue(pair.Key, out var before) || before != pair.Value) +
                         current.Keys.Count(key => !next.ContainsKey(key));

        var body = next
            .OrderBy(pair => pair.Value.Type, StringComparer.Ordinal)
            .ThenBy(pair => pair.Key, StringComparer.Ordinal)
            .Select(pair => $"{Indent}[RecipeType.{pair.Key}] = new {pair.Value.Type}({pair.Value.Arguments}),");

        var builder = new StringBuilder();
        builder.Append(string.Join(eol, lines.Take(open + 2)));
        builder.Append(eol);
        foreach (var line in body)
        {
            builder.Append(line);
            builder.Append(eol);
        }

        builder.Append(string.Join(eol, lines.Skip(close)));
        return builder.ToString();
    }
}
